def evaluate(expr):
    toks, i = [], 0
    while i < len(expr):
        c = expr[i]
        if c.isdigit():
            j = i
            while j < len(expr) and expr[j].isdigit():
                j += 1
            toks.append(int(expr[i:j])); i = j
        elif c in "+-*/()":
            toks.append(c); i += 1
        else:
            i += 1
    pos = 0
    def peek():
        return toks[pos] if pos < len(toks) else None
    def take():
        nonlocal pos
        pos += 1
        return toks[pos - 1]
    def atom():
        t = take()
        if t == "(":
            v = add(); take(); return v
        return t
    def mul():
        v = atom()
        while peek() in ("*", "/"):
            op, r = take(), atom()
            v = v * r if op == "*" else int(v / r) if (v < 0) != (r < 0) else v // r
        return v
    def add():
        v = mul()
        while peek() in ("+", "-"):
            op, r = take(), mul()
            v = v + r if op == "+" else v - r
        return v
    return add()
```

